select json_build_object('brands',(select count(*) from gym_brands),'locations',(select count(*) from gym_locations),'active_locations',(select count(*) from gym_locations where is_active),'training_sources',(select count(*) from training_sources),'equipment',(select count(*) from location_equipment),'capabilities',(select count(*) from location_training_capabilities),'evidence',(select count(*) from training_evidence),'published_equipment',(select count(*) from published_location_equipment),'published_capabilities',(select count(*) from published_location_training_capabilities),'hyrox_published',(select count(*) from published_location_training_disciplines where discipline_slug='hyrox'),'hyrox_official',(select official_location_count from published_training_discipline_summary where slug='hyrox'),'hyrox_search',(select max(total_count) from search_training_locations('hyrox',p_limit=>100)),'program_mappings',(select count(*) from program_training_disciplines),'classes',(select count(*) from class_schedules),'equipment_taxonomy',(select count(*) from equipment_types),'capability_taxonomy',(select count(*) from training_capability_types),'target_authority',(select count(*) from targets t join gym_locations l on l.id=t.location_id::uuid and l.is_active join location_external_identifiers x on x.location_id=t.location_id::uuid and x.namespace='hyrox-training-club' and x.external_identifier=t.hgy_id join published_training_affiliations a on a.location_id=t.location_id::uuid and a.discipline_slug='hyrox' and a.is_official),'source_collisions',(select count(*) from sources i join training_sources s on s.canonical_url=i.canonical_url or (s.location_id=i.location_id::uuid and s.url=i.url)),'evidence_collisions',(select count(*) from evidence_hashes i join training_evidence e using(content_hash))) result;
